def transform(grid):
    h, w = len(grid), len(grid[0])

    # Locate the uniform divider separating two equal-sized panels.
    divider = None
    for r in range(h):
        if h % 2 == 1 and r == h // 2 and len(set(grid[r])) == 1:
            divider = ("row", r, grid[r][0])
            break
    if divider is None:
        for c in range(w):
            if w % 2 == 1 and c == w // 2 and all(row[c] == grid[0][c] for row in grid):
                divider = ("col", c, grid[0][c])
                break

    if divider is None:
        return grid

    axis, pos, divider_color = divider
    if axis == "row":
        a, b = grid[:pos], grid[pos + 1:]
        colors_a = {v for row in a for v in row}
        colors_b = {v for row in b for v in row}
        shared = colors_a & colors_b
        shared.discard(divider_color)
        background = next(iter(shared), 0)
        return [
            [3 if a[r][c] == b[r][c] else background for c in range(w)]
            for r in range(len(a))
        ]
